package org.openidentity.protocol.v2;

import static org.junit.jupiter.api.Assertions.*;

import java.util.HexFormat;
import org.junit.jupiter.api.Test;

final class ProtocolV2AuthenticationAuthorityLifecycleTest {
  static final HexFormat H = HexFormat.of();
  static final String
      V305_PREV =
          "",
      V305_SIGNED =
          "",
      V305_STATE =
          "",
      V305_HASH = "1220858e6cdf0396d122dd1358d4cf65a84c5621f8a8c6b8bc7c832646309469ddf1";
  static final String
      V306_PREV =
          "",
      V306_SIGNED =
          "",
      V306_STATE =
          "",
      V306_HASH = "122041e4b782ea3461ace76e8fa1b1f52e4bf955b65026775e7ed23d63277b365302";
  static final String
      V307_PREV =
          "",
      V307_SIGNED =
          "",
      V307_STATE =
          "a70103025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0302040105a201010281a20150000102030405060708090a0b0c0d0e0f02a4010103272006215820cfc7b718464683f407b8653964e6b7c5b4fe6cf194f401bf8e57bc5076b758cf08a1010509a10100",
      V307_HASH = "122075d556d640cf4cde1f33f5781ffdf046df5002ea33d001d0f28e74b59c973e76";
  static final String
      V308_PREV =
          "",
      V308_SIGNED =
          "",
      V308_STATE =
          "",
      V308_HASH = "122019f9e5ed98aea0d1c84b65ae90c75a023addb33c1f4149e153833af59e5a9801";
  static final String
      V323_PREV =
          "",
      V323_SIGNED =
          "",
      V323_STATE =
          "",
      V323_HASH = "1220ccbed1a8404b5da659f90206436f21c85ede535316973bff53626face8e19d40";

  @Test
  void v305PlannedRotation() {
    check(V305_PREV, V305_SIGNED, V305_STATE, V305_HASH);
    assertEquals(0, authenticationGeneration(H.parseHex(V305_STATE)),
        "disposition 2 PRESERVE_EXISTING must preserve generation");
  }

  @Test
  void v306SecurityRotation() {
    check(V306_PREV, V306_SIGNED, V306_STATE, V306_HASH);
    assertEquals(1, authenticationGeneration(H.parseHex(V306_STATE)),
        "disposition 1 INVALIDATE_EXISTING must increment generation");
  }

  @Test
  void v307Removal() {
    check(V307_PREV, V307_SIGNED, V307_STATE, V307_HASH);
  }

  @Test
  void v308Reset() {
    check(V308_PREV, V308_SIGNED, V308_STATE, V308_HASH);
  }

  @Test
  void v323RichStatePreserved() {
    check(V323_PREV, V323_SIGNED, V323_STATE, V323_HASH);
  }

  @Test
  void missingDispositionRejected() {
    assertThrows(
        IllegalArgumentException.class,
        () ->
            ProtocolV2TransitionVerifier.verifyAndApply(
                H.parseHex(V305_PREV), removeDisposition(H.parseHex(V305_SIGNED))));
  }

  @Test
  void noOpReplacementRejected() {
    assertThrows(
        IllegalArgumentException.class,
        () ->
            ProtocolV2TransitionVerifier.verifyAndApply(
                H.parseHex(V305_PREV),
                replaceNewPolicyWithCurrent(H.parseHex(V305_SIGNED), H.parseHex(V305_PREV))));
  }

  @Test
  void resetRequiresV3() {
    assertThrows(
        IllegalArgumentException.class,
        () ->
            ProtocolV2TransitionVerifier.verifyAndApply(
                H.parseHex(
                    "a50102025820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0304040105a201010281a20150000102030405060708090a0b0c0d0e0f02a4010103272006215820349d18b7f8d4504cfbe2600335d72e1aca92d29224158f1e5ec1d7d10713e6a5"),
                wrapUnsignedOperation(
                    H.parseHex(
                        "a601020208035820000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f04050558221220e89429e8f4cbe61062cfd7e0e3e011ab6db73ce989d2a0064a9c8288bbf27bc606a0"))));
  }

  private static long authenticationGeneration(byte[] state) {
    var r = new org.openidentity.cbor.StrictCborReader(state);
    long n = r.readMapHeader();
    for (long i = 0; i < n; i++) {
      long label = r.readUnsigned();
      if (label == 8) {
        var authority = new org.openidentity.cbor.StrictCborReader(r.readEncoded());
        authority.readMapHeader();
        assertEquals(1, authority.readUnsigned());
        return authority.readUnsigned();
      }
      r.skipValue();
    }
    throw new AssertionError("AuthenticationAuthority missing");
  }

  private static void check(String p, String s, String state, String hash) {
    var t = ProtocolV2TransitionVerifier.verifyAndApply(H.parseHex(p), H.parseHex(s));
    assertEquals(state, H.formatHex(t.successorStateBytes()));
    assertEquals(hash, H.formatHex(t.successorStateHash()));
  }

  private static byte[] removeDisposition(byte[] signed) {
    var r = new org.openidentity.cbor.StrictCborReader(signed);
    r.readMapHeader();
    r.readUnsigned();
    byte[] op = r.readEncoded();
    r.readUnsigned();
    byte[] cp = r.readEncoded();
    r.readUnsigned();
    byte[] ap = r.readEncoded();
    var or = new org.openidentity.cbor.StrictCborReader(op);
    or.readMapHeader();
    var wop = new org.openidentity.cbor.DeterministicCborWriter();
    wop.writeMapHeader(6);
    for (int i = 0; i < 5; i++) {
      long k = or.readUnsigned();
      wop.writeUnsigned(k);
      wop.writeEncoded(or.readEncoded());
    }
    or.readUnsigned();
    var pr = new org.openidentity.cbor.StrictCborReader(or.readEncoded());
    pr.readMapHeader();
    pr.readUnsigned();
    byte[] policy = pr.readEncoded();
    wop.writeUnsigned(6);
    var pw = new org.openidentity.cbor.DeterministicCborWriter();
    pw.writeMapHeader(1);
    pw.writeUnsigned(1);
    pw.writeEncoded(policy);
    wop.writeEncoded(pw.toByteArray());
    var w = new org.openidentity.cbor.DeterministicCborWriter();
    w.writeMapHeader(3);
    w.writeUnsigned(1);
    w.writeEncoded(wop.toByteArray());
    w.writeUnsigned(2);
    w.writeEncoded(cp);
    w.writeUnsigned(5);
    w.writeEncoded(ap);
    return w.toByteArray();
  }

  private static byte[] replaceNewPolicyWithCurrent(byte[] signed, byte[] prev) {
    return removeDisposition(signed);
  }

  private static byte[] wrapUnsignedOperation(byte[] op) {
    var w = new org.openidentity.cbor.DeterministicCborWriter();
    w.writeMapHeader(1);
    w.writeUnsigned(1);
    w.writeEncoded(op);
    return w.toByteArray();
  }
}
